package help.galaw.standalone

import android.app.AlertDialog
import android.os.Bundle
import android.widget.*
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.view.View
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import org.json.JSONObject
import kotlin.concurrent.thread

class MainActivity : AppCompatActivity() {
    private lateinit var api:ApiClient; private lateinit var root:LinearLayout; private var selectedCase:Int?=null
    private val pickEvidence=registerForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        uri ?: return@registerForActivityResult
        val id=selectedCase ?: return@registerForActivityResult toast("Open a case first")
        busy("Uploading evidence…") { api.upload(id,uri); runOnUiThread { toast("Evidence uploaded and integrity hash created"); showCase(id) } }
    }
    override fun onCreate(savedInstanceState:Bundle?){ super.onCreate(savedInstanceState); api=ApiClient(this); if(api.token==null) showAuth() else showHome() }
    private val blue = Color.rgb(40,169,255)
    private val navy = Color.rgb(4,18,31)
    private val card = Color.rgb(11,35,54)
    private fun base(){ root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,38,28,34);setBackgroundColor(navy)};setContentView(ScrollView(this).apply{setBackgroundColor(navy);addView(root)}) }
    private fun label(s:String,z:Float=16f)=TextView(this).apply{text=s;textSize=z;setTextColor(Color.WHITE);setPadding(0,8,0,8)}
    private fun field(h:String,pass:Boolean=false)=EditText(this).apply{hint=h;setHintTextColor(Color.rgb(155,174,190));setTextColor(Color.WHITE);setPadding(28,20,28,20);background=GradientDrawable().apply{cornerRadius=44f;setColor(Color.rgb(12,39,59));setStroke(2,blue)};if(pass) inputType=129}
    private fun button(s:String, f:()->Unit)=Button(this).apply{text=s;isAllCaps=false;setTextColor(Color.WHITE);textSize=15f;background=GradientDrawable().apply{cornerRadius=28f;setColor(card);setStroke(1,Color.rgb(29,67,94))};setOnClickListener{f()}}
    private fun homeCard(title:String,subtitle:String,action:()->Unit)=LinearLayout(this).apply{
        orientation=LinearLayout.VERTICAL;setPadding(24,22,24,22);background=GradientDrawable().apply{cornerRadius=28f;setColor(card);setStroke(1,Color.rgb(28,64,89))}
        addView(label(title,18f).apply{setTypeface(typeface,Typeface.BOLD)});addView(label(subtitle,13f).apply{setTextColor(Color.rgb(174,193,207))});setOnClickListener{action()}
    }
    private fun addHomeRow(vararg views:View){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};views.forEach{row.addView(it,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f).apply{setMargins(5,6,5,6)})};root.addView(row)}

    private fun showAuth(){ base();root.addView(label("STANDALONE ASSISTANT",14f));root.addView(label("GA.LAW.HELP",30f));val e=field("Email");val p=field("Password (10+ characters)",true);root.addView(e);root.addView(p);root.addView(button("Log in"){busy("Signing in…"){api.auth("/auth/login",e.text.toString(),p.text.toString());runOnUiThread{showHome()}}});root.addView(button("Create account"){busy("Creating account…"){val result=api.auth("/auth/register",e.text.toString(),p.text.toString());runOnUiThread{if(result.optBoolean("verification_required")) showVerification(e.text.toString()) else showHome()}}});root.addView(button("Verify email"){showVerification(e.text.toString())});root.addView(button("Forgot password"){showPasswordReset(e.text.toString())}) }
    private fun showVerification(email:String){base();root.addView(label("VERIFY EMAIL",26f));root.addView(label("Open the verification email sent to $email. You can also paste its token below."));val t=field("Verification token");root.addView(t);root.addView(button("Verify"){busy("Verifying…"){api.verifyEmail(t.text.toString());runOnUiThread{toast("Email verified. Log in now.");showAuth()}}});root.addView(button("Resend email"){busy("Sending…"){api.resendVerification(email);runOnUiThread{toast("If the account exists, a new email was sent.")}}});root.addView(button("Back"){showAuth()})}
    private fun showPasswordReset(email:String){base();root.addView(label("RESET PASSWORD",26f));val e=field("Email").apply{setText(email)};val token=field("Reset token");val password=field("New password (12+ characters)",true);root.addView(e);root.addView(button("Send reset email"){busy("Sending…"){api.forgotPassword(e.text.toString());runOnUiThread{toast("If the account exists, a reset email was sent.")}}});root.addView(token);root.addView(password);root.addView(button("Set new password"){busy("Resetting…"){api.resetPassword(token.text.toString(),password.text.toString());runOnUiThread{toast("Password changed. Log in now.");showAuth()}}});root.addView(button("Back"){showAuth()})}
    private fun showHome(){selectedCase=null;base()
        root.addView(label("GA.LAW.HELP",30f).apply{setTypeface(typeface,Typeface.BOLD)})
        root.addView(label("KNOW YOUR RIGHTS. PROTECT YOUR FUTURE.",12f).apply{setTextColor(Color.rgb(148,166,180))})
        root.addView(label("LEGAL ANSWERS\nANYTIME.",29f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,30,0,4)})
        root.addView(label("Understand your rights. Get guidance.\nStay informed. Be prepared.",15f).apply{setTextColor(Color.rgb(190,205,215))})
        val ask=field("Ask GA.LAW.HELP anything…");root.addView(ask,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,24,0,8)});root.addView(button("Ask AI"){val q=ask.text.toString().trim();if(q.isNotEmpty()) busy("Asking GA.LAW.HELP…"){val result=api.publicAsk(q);runOnUiThread{showAnswer("GA.LAW.HELP",result.optString("answer",result.toString()))}}})
        addHomeRow(button("🎙 Voice Help"){showGuide("VOICE HELP","Use this screen to prepare what you want to ask. During a police encounter, stay calm, do not physically resist, and follow lawful safety instructions. GA.LAW.HELP provides legal information, not attorney representation.")},button("▣ Upload a Document"){showDocumentIntake()},button("▣ Scan / Take Photo"){showDocumentIntake(true)})
        addHomeRow(homeCard("🛡 Know My Rights","Simple answers for real situations"){showGuide("KNOW MY RIGHTS","Choose the situation you are dealing with and review plain-language legal information before deciding what to do. If you are in immediate danger, use emergency services.")},homeCard("🚙 Traffic Stop","What to do and what to say"){showGuide("TRAFFIC STOP","Stay calm. Keep your hands visible. Avoid sudden movements. You can ask whether you are free to leave and clearly state that you do not consent to a search. Do not physically resist. The exact law can depend on the facts.")},homeCard("♟ Questioned by Police","Stay calm. Know your rights."){showGuide("QUESTIONED BY POLICE","You can clearly say that you wish to remain silent and want a lawyer. Do not lie, threaten, obstruct, or physically resist. Whether questioning may continue depends on the circumstances.")})
        addHomeRow(homeCard("⛓ Arrested / Detained","Step-by-step help"){showGuide("ARRESTED / DETAINED","Stay calm and do not physically resist. Ask whether you are free to leave. If you are being questioned while in custody, clearly request a lawyer and state that you wish to remain silent.")},homeCard("⚖ Georgia Laws","Search laws, penalties & more"){showLawSearch()},homeCard("▤ Funny & Weird Georgia Laws","Learn something new"){toast("Funny & Weird Georgia Laws")})
        addHomeRow(homeCard("💬 Ask GA.LAW.HELP","Get legal guidance with AI"){ask.requestFocus()},homeCard("⚖ "+tr("motions"),"For pending cases or incarceration"){showLegalWorkHub()},homeCard("📁 My Documents","Store and manage your files"){showDocuments()},homeCard("▥ My Recordings","Your audio, saved securely"){showRecordings()})
        root.addView(button("⚠  EMERGENCY INFORMATION"){toast("For immediate danger, contact emergency services.")},LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,14,0,10)})
        root.addView(label("Knowledge is power, especially when you need it most.",14f).apply{gravity=android.view.Gravity.CENTER;setTextColor(Color.rgb(157,176,190));setPadding(0,18,0,18)})
        root.addView(button("🗣 "+tr("talk")){showTalkToMe()});root.addView(button("⚙ "+tr("settings")){showLanguageSettings()});root.addView(label("Home        ⚖ Laws        💬 AI Help        📁 Documents        ● Account",13f).apply{gravity=android.view.Gravity.CENTER;setTextColor(blue)})
    }
    private fun languageCode():String { val saved=getSharedPreferences("ga_settings",MODE_PRIVATE).getString("language","English")?:"English"; return when { saved.startsWith("Español")->"es"; saved.startsWith("中文")->"zh"; saved.startsWith("Français")->"fr"; saved.startsWith("العربية")->"ar"; saved.startsWith("Tiếng Việt")->"vi"; else->"en" } }
    private fun tr(key:String):String { val en=mapOf("talk" to "Talk to Me","settings" to "Settings / Language","back" to "← Home","send" to "Send","language" to "LANGUAGE","motions" to "Motions & Legal Work"); val es=mapOf("talk" to "Habla conmigo","settings" to "Configuración / Idioma","back" to "← Inicio","send" to "Enviar","language" to "IDIOMA","motions" to "Mociones y trabajo legal"); val zh=mapOf("talk" to "与我交谈","settings" to "设置 / 语言","back" to "← 首页","send" to "发送","language" to "语言","motions" to "动议与法律工作"); val fr=mapOf("talk" to "Parlez-moi","settings" to "Paramètres / Langue","back" to "← Accueil","send" to "Envoyer","language" to "LANGUE","motions" to "Requêtes et travail juridique"); val ar=mapOf("talk" to "تحدث معي","settings" to "الإعدادات / اللغة","back" to "← الرئيسية","send" to "إرسال","language" to "اللغة","motions" to "الطلبات والعمل القانوني"); val vi=mapOf("talk" to "Nói chuyện với tôi","settings" to "Cài đặt / Ngôn ngữ","back" to "← Trang chủ","send" to "Gửi","language" to "NGÔN NGỮ","motions" to "Kiến nghị & Công việc pháp lý"); return when(languageCode()){"es"->es;"zh"->zh;"fr"->fr;"ar"->ar;"vi"->vi;else->en}[key]?:en[key]?:key }
    private fun legalLanguageInstruction():String = when(languageCode()){"es"->"Respond in Spanish unless quoting an authority that should remain in its original language.";"zh"->"Respond in Simplified Chinese unless quoting an authority that should remain in its original language.";"fr"->"Respond in French unless quoting an authority that should remain in its original language.";"ar"->"Respond in Arabic unless quoting an authority that should remain in its original language.";"vi"->"Respond in Vietnamese unless quoting an authority that should remain in its original language.";else->"Respond in English."}
    private fun showTalkToMe(){base();root.addView(button(tr("back")){showHome()});root.addView(label("TALK TO ME",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Have a back-and-forth conversation about Georgia law, rights, police encounters, cases, motions, sentencing, incarceration, appeals, or verified programs.",14f).apply{setTextColor(Color.rgb(174,193,207))});val history=StringBuilder();val q=field("What do you want to talk about?");val conversation=label("",15f);root.addView(conversation);root.addView(q);root.addView(button(tr("send")){val message=q.text.toString().trim();if(message.isNotEmpty()){val prompt="Continue a focused GA.LAW.HELP legal-information conversation. "+legalLanguageInstruction()+" Stay within Georgia law, rights, police encounters, criminal/civil legal procedure, motions, sentencing, incarceration/post-conviction issues, appeals, and verified legal programs. Do not answer unrelated general-chat questions. Conversation so far:\n"+history+"\nUser: "+message;busy("Thinking…"){val answer=api.publicAsk(prompt).optString("answer");history.append("User: ").append(message).append("\nGA.LAW.HELP: ").append(answer).append("\n\n");runOnUiThread{conversation.text=history.toString();q.setText("")}}}});root.addView(label("This conversation is not saved to a case unless you choose to save legal work separately.",13f).apply{setTextColor(Color.rgb(148,166,180))})}
    private fun showLanguageSettings(){base();root.addView(button("← Home"){showHome()});root.addView(label(tr("language"),27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Choose the app language. Full interface translation will be rolled out through this setting.",14f));arrayOf("English","Español (Spanish)","中文 (Chinese)","Français (French)","العربية (Arabic)","Tiếng Việt (Vietnamese)").forEach{language->root.addView(button(language){getSharedPreferences("ga_settings",MODE_PRIVATE).edit().putString("language",language).apply();toast("Language preference saved: $language. AI legal conversations will use this language.")})}}
    private fun showLegalWorkHub(){base();root.addView(button("← Home"){showHome()});root.addView(label("MOTIONS & LEGAL WORK",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Research first. Saving a case is optional.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("I am NOT incarcerated"){showLegalWorkPath("PENDING / COMMUNITY CASE","Research potentially relevant pretrial, evidence, discovery, bond, probation, sentencing, and other Georgia procedures. GA.LAW.HELP should verify the case stage, facts, deadlines, and legal authority before suggesting a motion.")});root.addView(button("I am incarcerated"){showLegalWorkPath("INCARCERATED / POST-CONVICTION","Research potentially relevant appellate, post-conviction, sentence, habeas, records/evidence, and verified program issues. Availability and deadlines depend on the judgment, procedural history, custody status, and current law.")});root.addView(button("Research without saving a case"){showGuide("LEGAL RESEARCH","Ask questions and investigate possible procedures without creating a saved case. If something becomes useful, you can later save the research to a case and build a draft for review.")})}
    private fun showLegalWorkPath(title:String,body:String){base();root.addView(button("← Motions & Legal Work"){showLegalWorkHub()});root.addView(label(title,24f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,10)});root.addView(label(body,15f));root.addView(label("A motion draft must identify its purpose, legal authority, required facts, timing/deadlines, supporting evidence, likely counterarguments, and uncertainties. Drafts are for review and are not automatically filed.",14f).apply{setTextColor(Color.rgb(174,193,207));setPadding(0,18,0,10)});root.addView(button("Ask GA.LAW.HELP about my situation"){showHome()});root.addView(button("Save / work inside a case"){showDocuments()})}
    private fun showDocumentIntake(imagesOnly:Boolean=false){base();root.addView(button("← Home"){showHome()});root.addView(label(if(imagesOnly) "SCAN / TAKE PHOTO" else "UPLOAD A DOCUMENT",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Choose the case this belongs to. Your upload will be stored in that case's evidence workspace with its integrity hash.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("＋ Create a new case"){newCase()});busy("Loading your cases…"){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("No case exists yet. Create one first so the file has a secure case workspace.",15f));for(i in 0 until cases.length()){val x=cases.optJSONObject(i)?:continue;val id=x.optInt("id");root.addView(button("Add to "+x.optString("title","Case #$id")){selectedCase=id;pickEvidence.launch(if(imagesOnly) arrayOf("image/*") else arrayOf("*/*"))})}}}}
    private fun showRecordings(){base();root.addView(button("← Home"){showHome()});root.addView(label("MY RECORDINGS",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Law-enforcement and legal-situation recordings",15f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(label("Recording is intentionally not activated yet. Before microphone capture is enabled, GA.LAW.HELP will show a clear recording indicator, explain storage and deletion controls, and require the user to confirm that recording is lawful in their situation.",15f).apply{setPadding(0,20,0,12)});root.addView(label("Planned retention: user-controlled, with the requested 180–400 day range available as an option. The app will not silently start recording.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("Recording privacy & controls"){showGuide("RECORDING PRIVACY","Recordings are intended only for law-enforcement interactions or legal situations. Microphone access will require explicit permission and a visible active-recording state. Users will have deletion and retention controls before this feature is released.")})}
    private fun showDocuments(){base();root.addView(button("← Home"){showHome()});root.addView(label("MY DOCUMENTS",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Your case files and uploaded evidence",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("＋ Create Case"){newCase()});busy("Loading your cases…"){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("No case files yet. Create a case to securely organize documents and evidence.",15f));for(i in 0 until cases.length()){val x=cases.optJSONObject(i)?:continue;val id=x.optInt("id");root.addView(button("📁 "+x.optString("title","Case #$id")){showCase(id)})}}}}
    private fun showAnswer(title:String,body:String){base();root.addView(button("← Home"){showHome()});root.addView(label(title,27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,14)});root.addView(label(body,16f).apply{setTextColor(Color.rgb(205,218,227))})}
    private fun showLawSearch(){base();root.addView(button("← Home"){showHome()});root.addView(label("GEORGIA LAWS",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,12)});val q=field("Search Georgia laws…");root.addView(q);root.addView(button("Search"){val s=q.text.toString().trim();if(s.isNotEmpty())busy("Searching Georgia law…"){val arr=api.searchAuthorities(s);val out=StringBuilder();for(i in 0 until arr.length()){val x=arr.optJSONObject(i)?:continue;out.append(x.optString("citation",x.optString("title","Georgia authority"))).append("\n").append(x.optString("title")).append("\n\n")};runOnUiThread{showAnswer("SEARCH RESULTS",if(out.isEmpty()) "No indexed authority matched that search." else out.toString())}}})}
    private fun showGuide(title:String,body:String){base();root.addView(button("← Home"){showHome()});root.addView(label(title,27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,14)});root.addView(label(body,16f).apply{setTextColor(Color.rgb(205,218,227))});root.addView(label("Important: GA.LAW.HELP provides legal information and does not create an attorney-client relationship.",13f).apply{setTextColor(Color.rgb(148,166,180));setPadding(0,24,0,8)})}
    private fun newCase(){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(30,0,30,0)};val t=field("Case title");val c=field("Georgia county/circuit");val s=field("Stage (pretrial, appeal, habeas…)");val n=field("Tell us what happened");listOf(t,c,s,n).forEach{box.addView(it)};AlertDialog.Builder(this).setTitle("New case").setView(box).setPositiveButton("Create"){_,_->busy("Creating case…"){val o=api.createCase(t.text.toString(),c.text.toString(),s.text.toString(),n.text.toString());runOnUiThread{showCase(o.getInt("id"))}}}.setNegativeButton("Cancel",null).show()}
    private fun showCase(id:Int){selectedCase=id;base();root.addView(button("← My Cases"){showHome()});root.addView(label("CASE WORKSPACE",26f));busy("Loading case…"){val c=api.caseDetail(id);val ev=api.evidence(id);val tl=api.timeline(id);runOnUiThread{root.addView(label(c.optString("title","Case #$id"),22f));root.addView(label("${c.optString("county","")} • ${c.optString("stage","")}",13f));root.addView(button("⚖ Analyze Case"){runAnalysis(id)});root.addView(button("Why? — Sources & Authority"){showWhy(id)});root.addView(button("Red-Team My Case"){showRedTeam(id)});root.addView(button("Second-Look / Appeal Review"){showSecondLook(id)});root.addView(button("＋ Add evidence / video / document"){pickEvidence.launch(arrayOf("*/*"))});root.addView(label("EVIDENCE",14f));for(i in 0 until ev.length()){val o=ev.getJSONObject(i);root.addView(label("✓ ${o.optString("filename")}\nSHA-256: ${o.optString("sha256").take(20)}…",13f))};root.addView(label("MASTER TIMELINE",14f));for(i in 0 until tl.length()){val o=tl.getJSONObject(i);root.addView(label("${o.optString("title")} • ${o.optString("source_label")}",14f))}}}}
    private fun runAnalysis(id:Int)=busy("Screening case…"){val o=api.runAnalysis(id);runOnUiThread{showJsonFindings("CASE INTELLIGENCE",o,"findings")}}
    private fun showWhy(id:Int)=busy("Loading authority…"){val o=api.why(id);runOnUiThread{showJsonFindings("WHY? — VERIFIED AUTHORITY",o,"why")}}
    private fun showRedTeam(id:Int)=busy("Red-teaming…"){val o=api.redTeam(id);runOnUiThread{showJsonFindings("RED-TEAM",o,"items")}}
    private fun showSecondLook(id:Int)=busy("Running second-look…"){val o=api.secondLook(id);runOnUiThread{showJsonFindings("SECOND-LOOK",o,"screening")}}
    private fun showJsonFindings(title:String,o:JSONObject,key:String){base();root.addView(button("← Case"){selectedCase?.let{showCase(it)}});root.addView(label(title,24f));val a=o.optJSONArray(key);if(a==null||a.length()==0){root.addView(label("No verified results are attached yet. Add more case facts/records or link verified authority."));return};for(i in 0 until a.length()){val x=a.getJSONObject(i);val head=x.optString("issue",x.optString("proposition","Finding ${i+1}"));val body=x.optString("analysis",x.optString("citation",x.toString()));val counter=x.optString("counterargument","");root.addView(label(head,18f));root.addView(label(body,14f));if(counter.isNotBlank())root.addView(label("Counterargument: $counter",13f))}}
    private fun busy(msg:String,job:()->Unit){toast(msg);thread{try{job()}catch(e:Exception){runOnUiThread{toast(e.message?:"Request failed")}}}}
    private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_LONG).show()
}
